css:
.print-format {
  font-family: "Helvetica", "Arial", sans-serif;
  font-size: 14px;
  color: #000;
}

h3 {
  font-weight: bold;
  margin: 0;
  padding: 0;
}

p {
  margin: 2px 0;
}

table td {
  padding: 3px 0;
}

.line {
  border-bottom: 1px solid #000;
  padding-bottom: 4px;
  margin-bottom: 10px;
}
